import ipaddress

DNS = {  # pretend TXT lookups
    "corp.example": "v=spf1 ip4:192.0.2.0/24 include:_spf.mailer.example -all",
    "_spf.mailer.example": "v=spf1 ip4:198.51.100.0/24 -all",
}
QUAL = {"+": "pass", "-": "fail", "~": "softfail", "?": "neutral"}


def check_host(ip, domain, lookups=0):
    for term in DNS[domain].split()[1:]:
        q = term[0] if term[0] in QUAL else "+"
        mech = term.lstrip("+-~?")
        if mech.startswith("ip4:"):
            if ipaddress.ip_address(ip) in ipaddress.ip_network(mech[4:]):
                return QUAL[q], lookups
        elif mech.startswith("include:"):
            lookups += 1  # counts toward the limit of 10
            res, lookups = check_host(ip, mech[8:], lookups)
            if res == "pass":
                return QUAL[q], lookups
        elif mech == "all":
            return QUAL[q], lookups
    return "neutral", lookups


for ip in ["192.0.2.25", "198.51.100.7", "203.0.113.9"]:
    print(ip, check_host(ip, "corp.example"))

