def org(domain):
    # Simplified: last two labels. RFC 9989 finds the real
    # Organizational Domain with a DNS tree walk.
    return ".".join(domain.lower().split(".")[-2:])


def aligned(auth_domain, from_domain, mode="r"):
    if mode == "s":
        return auth_domain.lower() == from_domain.lower()
    return org(auth_domain) == org(from_domain)


def dmarc(from_dom, spf_res, spf_dom, dkim_res, dkim_dom):
    spf_ok = spf_res == "pass" and aligned(spf_dom, from_dom)
    dkim_ok = dkim_res == "pass" and aligned(dkim_dom, from_dom)
    return "pass" if (spf_ok or dkim_ok) else "fail"


