import email
import re
import sys
from email import policy

TRUSTED = "mx.corp.example"  # authserv-id of OUR border MTA


def auth_results(msg):
    # Use only the topmost header our own server added (RFC 8601).
    for ar in msg.get_all("Authentication-Results", []):
        if ar.split(";", 1)[0].strip() == TRUSTED:
            return dict(re.findall(r"\b(spf|dkim|dmarc)=(\w+)", ar))
    return {}


def triage(raw):
    msg = email.message_from_string(raw, policy=policy.default)
    res = auth_results(msg)
    sender = msg["From"].addresses[0]
    flags = [f"{k}={res.get(k, 'missing')}"
             for k in ("spf", "dkim", "dmarc") if res.get(k) != "pass"]
    if msg["Reply-To"]:
        reply = msg["Reply-To"].addresses[0]
        if reply.domain.lower() != sender.domain.lower():
            flags.append("reply-to domain " + reply.domain)
    hops = msg.get_all("Received", [])
    seen = re.search(r"\[([\d.]+)\]", hops[0])  # our MX's own view
    print("From:   ", sender.display_name, "<" + sender.addr_spec + ">")
    print("Sent by:", seen.group(1) if seen else "unknown",
          "| hops:", len(hops))
    print("Verdict:", "SUSPICIOUS" if flags else "no auth flags", flags)


if __name__ == "__main__":
    triage(open(sys.argv[1]).read())

import { createHash } from "node:crypto";

const RP_ID = "corp.example";
const ORIGIN = "https://login.corp.example";

function checkAssertion(clientDataJSON, rpIdHash, expectedChallenge) {
  const c = JSON.parse(Buffer.from(clientDataJSON, "base64url"));
  if (c.type !== "webauthn.get") return "reject: wrong type";
  if (c.challenge !== expectedChallenge) return "reject: stale challenge";
  if (c.origin !== ORIGIN) return "reject: origin " + c.origin;
  const want = createHash("sha256").update(RP_ID).digest("hex");
  if (rpIdHash !== want) return "reject: rpIdHash";
  return "ok so far: now verify the signature with the stored public key";
}

