import json

OUR_DOMAINS = {"corp.example"}
WATCH = {"invoice", "payment", "wire", "bank", "remittance"}

rules = json.loads("""[
 {"mailbox": "pat@corp.example", "name": "Newsletters",
  "if_words": ["digest"], "move_to": "Reading", "forward_to": null},
 {"mailbox": "pat@corp.example", "name": ".",
  "if_words": ["invoice", "bank"], "move_to": "RSS Feeds", "forward_to": null},
 {"mailbox": "lee@corp.example", "name": "sync",
  "if_words": [], "move_to": null, "forward_to": "lee.backup@freemail.example"}
]""")


def risky(rule):
    why = []
    hits = WATCH & {w.lower() for w in rule["if_words"]}
    if hits and rule["move_to"] in {"RSS Feeds", "Archive", "Deleted Items"}:
        why.append("hides " + "/".join(sorted(hits)) + " mail")
    fwd = rule["forward_to"]
    if fwd and fwd.split("@")[-1] not in OUR_DOMAINS:
        why.append("forwards to external " + fwd)
    if len(rule["name"].strip(" .")) == 0:
        why.append("blank-looking name")
    return why


for r in rules:
    if why := risky(r):
        print(r["mailbox"], "|", r["name"], "|", "; ".join(why))

# Output:
# pat@corp.example | . | hides bank/invoice mail; blank-looking name
# lee@corp.example | sync | forwards to external lee.backup@freemail.example
